import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Tradeboard MQL5 Functions","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/metatrader-5/openalgo-mql5-functions.md","filePath":"trading-platform/metatrader-5/openalgo-mql5-functions.md"}'),r={name:"trading-platform/metatrader-5/openalgo-mql5-functions.md"};function o(i,a,l,d,p,c){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="tradeboard-mql5-functions" tabindex="-1">Tradeboard MQL5 Functions <a class="header-anchor" href="#tradeboard-mql5-functions" aria-label="Permalink to &quot;Tradeboard MQL5 Functions&quot;">​</a></h1><p>Below is the API documentation for the TradeboardAPI functions provided in your MQL5 header file:</p><hr><h2 id="tradeboardapi-function-documentation" tabindex="-1">TradeboardAPI Function Documentation <a class="header-anchor" href="#tradeboardapi-function-documentation" aria-label="Permalink to &quot;TradeboardAPI Function Documentation&quot;">​</a></h2><p>All six functions are <code>void</code>. They print the request and the Tradeboard response to the Experts log rather than returning a value, so read the log (or the Tradeboard order book) to confirm what happened.</p><p>Each function takes <code>apiUrlParam</code> as the base URL of your Tradeboard instance, for example <code>http://127.0.0.1:5000</code>, and appends the endpoint path itself.</p><h3 id="placeorder" tabindex="-1"><code>PlaceOrder</code> <a class="header-anchor" href="#placeorder" aria-label="Permalink to &quot;\`PlaceOrder\`&quot;">​</a></h3><p>Places an order with the specified parameters by sending a POST request to <code>/api/v1/placeorder</code>.</p><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void PlaceOrder(string actionParam,</span></span>
<span class="line"><span>                int quantityParam,</span></span>
<span class="line"><span>                string apiUrlParam,</span></span>
<span class="line"><span>                string apiKeyParam,</span></span>
<span class="line"><span>                string strategyParam,</span></span>
<span class="line"><span>                string symbolParam,</span></span>
<span class="line"><span>                Exchanges exchangeParam,</span></span>
<span class="line"><span>                ProductTypes productParam,</span></span>
<span class="line"><span>                PriceTypes priceTypeParam,</span></span>
<span class="line"><span>                double priceParam = 0,</span></span>
<span class="line"><span>                double triggerPriceParam = 0,</span></span>
<span class="line"><span>                int disclosedQuantityParam = 0)</span></span></code></pre></div><h4 id="parameters" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h4><ul><li><code>actionParam</code>: The trade action, either &quot;BUY&quot; or &quot;SELL&quot;.</li><li><code>quantityParam</code>: The quantity of the asset to trade, in units and not lots.</li><li><code>apiUrlParam</code>: The base URL of the Tradeboard API.</li><li><code>apiKeyParam</code>: The Tradeboard API key, generated on the API Key page of the dashboard. This is not your broker&#39;s API key.</li><li><code>strategyParam</code>: The name of the trading strategy. Tradeboard records it against every order.</li><li><code>symbolParam</code>: The Tradeboard symbol for the instrument being traded.</li><li><code>exchangeParam</code>: An <code>Exchanges</code> enum value (NSE, NFO, CDS, BSE, BFO, BCD, MCX, NCDEX).</li><li><code>productParam</code>: A <code>ProductTypes</code> enum value (CNC, NRML, MIS).</li><li><code>priceTypeParam</code>: A <code>PriceTypes</code> enum value (MARKET, LIMIT, SL, SLM). SLM is sent as <code>SL-M</code>.</li><li><code>priceParam</code> (optional): The price at which to place the order. Required for LIMIT and SL.</li><li><code>triggerPriceParam</code> (optional): The trigger price for SL and SL-M orders.</li><li><code>disclosedQuantityParam</code> (optional): The disclosed quantity of the order.</li></ul><p>The three optional numeric parameters are only written into the JSON body when they are greater than zero, so leaving them at their defaults keeps the payload minimal.</p><h4 id="usage" tabindex="-1">Usage: <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage:&quot;">​</a></h4><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PlaceOrder(&quot;BUY&quot;, 10, &quot;http://127.0.0.1:5000&quot;, &quot;your_api_key&quot;, &quot;Meta Strategy&quot;, &quot;SBIN&quot;, NSE, MIS, MARKET);</span></span></code></pre></div><h3 id="placesmartorder" tabindex="-1"><code>PlaceSmartOrder</code> <a class="header-anchor" href="#placesmartorder" aria-label="Permalink to &quot;\`PlaceSmartOrder\`&quot;">​</a></h3><p>Places an order that considers the current open position size and matches the position size given in the position book. Sends a POST request to <code>/api/v1/placesmartorder</code>.</p><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void PlaceSmartOrder(string actionParam,</span></span>
<span class="line"><span>                     int quantityParam,</span></span>
<span class="line"><span>                     int positionSizeParam,</span></span>
<span class="line"><span>                     string apiUrlParam,</span></span>
<span class="line"><span>                     string apiKeyParam,</span></span>
<span class="line"><span>                     string strategyParam,</span></span>
<span class="line"><span>                     string symbolParam,</span></span>
<span class="line"><span>                     Exchanges exchangeParam,</span></span>
<span class="line"><span>                     ProductTypes productParam,</span></span>
<span class="line"><span>                     PriceTypes priceTypeParam,</span></span>
<span class="line"><span>                     double priceParam = 0,</span></span>
<span class="line"><span>                     double triggerPriceParam = 0,</span></span>
<span class="line"><span>                     int disclosedQuantityParam = 0)</span></span></code></pre></div><h4 id="parameters-1" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h4><ul><li>Inherits all parameters from <code>PlaceOrder</code>.</li><li><code>positionSizeParam</code>: The target position size. It sits third, immediately after <code>quantityParam</code>.</li></ul><p>Tradeboard compares <code>positionSizeParam</code> with your live open position for that symbol, exchange and product, then places only the difference. A target of <code>0</code> flattens the position, and in that case Tradeboard works out the direction itself, so <code>actionParam</code> and <code>quantityParam</code> are ignored. If the position already matches the target, no order goes to the broker.</p><h4 id="usage-1" tabindex="-1">Usage: <a class="header-anchor" href="#usage-1" aria-label="Permalink to &quot;Usage:&quot;">​</a></h4><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PlaceSmartOrder(&quot;SELL&quot;, 5, 10, &quot;http://127.0.0.1:5000&quot;, &quot;your_api_key&quot;, &quot;ReversalStrategy&quot;, &quot;TATASTEEL&quot;, NSE, MIS, LIMIT, 150.00);</span></span></code></pre></div><h3 id="modifyorder" tabindex="-1"><code>ModifyOrder</code> <a class="header-anchor" href="#modifyorder" aria-label="Permalink to &quot;\`ModifyOrder\`&quot;">​</a></h3><p>Modifies an existing order with new parameters. Sends a POST request to <code>/api/v1/modifyorder</code>.</p><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void ModifyOrder(string orderidParam,</span></span>
<span class="line"><span>                 string actionParam,</span></span>
<span class="line"><span>                 int quantityParam,</span></span>
<span class="line"><span>                 double priceParam,</span></span>
<span class="line"><span>                 string apiUrlParam,</span></span>
<span class="line"><span>                 string apiKeyParam,</span></span>
<span class="line"><span>                 string strategyParam,</span></span>
<span class="line"><span>                 string symbolParam,</span></span>
<span class="line"><span>                 Exchanges exchangeParam,</span></span>
<span class="line"><span>                 ProductTypes productParam,</span></span>
<span class="line"><span>                 PriceTypes priceTypeParam,</span></span>
<span class="line"><span>                 int disclosedQuantityParam = 0,</span></span>
<span class="line"><span>                 double triggerPriceParam = 0)</span></span></code></pre></div><h4 id="parameters-2" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h4><ul><li><code>orderidParam</code>: The ID of the order to be modified, as returned by Tradeboard when the order was placed.</li><li><code>priceParam</code>: Mandatory here, unlike in <code>PlaceOrder</code>. It sits fourth, right after <code>quantityParam</code>.</li><li>The remaining parameters match <code>PlaceOrder</code>.</li></ul><p>Note the tail of the argument list: in <code>ModifyOrder</code> the optional <code>disclosedQuantityParam</code> comes BEFORE <code>triggerPriceParam</code>, which is the reverse of <code>PlaceOrder</code> and <code>PlaceSmartOrder</code>. <code>/api/v1/modifyorder</code> requires every field, so this function always sends price, quantity, disclosed quantity and trigger price, even when they are zero.</p><h4 id="usage-2" tabindex="-1">Usage: <a class="header-anchor" href="#usage-2" aria-label="Permalink to &quot;Usage:&quot;">​</a></h4><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ModifyOrder(&quot;123456789&quot;, &quot;BUY&quot;, 10, 155.00, &quot;http://127.0.0.1:5000&quot;, &quot;your_api_key&quot;, &quot;Meta Strategy&quot;, &quot;YESBANK&quot;, NSE, CNC, LIMIT);</span></span></code></pre></div><h3 id="cancelorder" tabindex="-1"><code>CancelOrder</code> <a class="header-anchor" href="#cancelorder" aria-label="Permalink to &quot;\`CancelOrder\`&quot;">​</a></h3><p>Cancels an existing order. Sends a POST request to <code>/api/v1/cancelorder</code>.</p><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void CancelOrder(string orderidParam,</span></span>
<span class="line"><span>                 string apiUrlParam,</span></span>
<span class="line"><span>                 string apiKeyParam,</span></span>
<span class="line"><span>                 string strategyParam)</span></span></code></pre></div><h4 id="parameters-3" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h4><ul><li><code>orderidParam</code>: The ID of the order to be canceled.</li><li><code>apiUrlParam</code>: The base URL of the Tradeboard API.</li><li><code>apiKeyParam</code>: The Tradeboard API key.</li><li><code>strategyParam</code>: The name of the trading strategy.</li></ul><h4 id="usage-3" tabindex="-1">Usage: <a class="header-anchor" href="#usage-3" aria-label="Permalink to &quot;Usage:&quot;">​</a></h4><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CancelOrder(&quot;123456789&quot;, &quot;http://127.0.0.1:5000&quot;, &quot;your_api_key&quot;, &quot;Meta Strategy&quot;);</span></span></code></pre></div><h3 id="closeposition" tabindex="-1"><code>ClosePosition</code> <a class="header-anchor" href="#closeposition" aria-label="Permalink to &quot;\`ClosePosition\`&quot;">​</a></h3><p>Closes all open positions associated with a given strategy. Sends a POST request to <code>/api/v1/closeposition</code>.</p><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void ClosePosition(string apiUrlParam,</span></span>
<span class="line"><span>                   string apiKeyParam,</span></span>
<span class="line"><span>                   string strategyParam)</span></span></code></pre></div><h4 id="parameters-4" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h4><ul><li><code>apiUrlParam</code>: The base URL of the Tradeboard API.</li><li><code>apiKeyParam</code>: The Tradeboard API key.</li><li><code>strategyParam</code>: The name of the trading strategy to close positions for.</li></ul><h4 id="usage-4" tabindex="-1">Usage: <a class="header-anchor" href="#usage-4" aria-label="Permalink to &quot;Usage:&quot;">​</a></h4><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ClosePosition(&quot;http://127.0.0.1:5000&quot;, &quot;your_api_key&quot;, &quot;Meta Strategy&quot;);</span></span></code></pre></div><h3 id="cancelallorders" tabindex="-1"><code>CancelAllOrders</code> <a class="header-anchor" href="#cancelallorders" aria-label="Permalink to &quot;\`CancelAllOrders\`&quot;">​</a></h3><p>Cancels all orders associated with a given strategy. Sends a POST request to <code>/api/v1/cancelallorder</code>.</p><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void CancelAllOrders(string apiUrlParam,</span></span>
<span class="line"><span>                     string apiKeyParam,</span></span>
<span class="line"><span>                     string strategyParam)</span></span></code></pre></div><h4 id="parameters-5" tabindex="-1">Parameters: <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters:&quot;">​</a></h4><ul><li><code>apiUrlParam</code>: The base URL of the Tradeboard API.</li><li><code>apiKeyParam</code>: The Tradeboard API key.</li><li><code>strategyParam</code>: The name of the trading strategy to cancel orders for.</li></ul><h4 id="usage-5" tabindex="-1">Usage: <a class="header-anchor" href="#usage-5" aria-label="Permalink to &quot;Usage:&quot;">​</a></h4><div class="language-mql5 vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mql5</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CancelAllOrders(&quot;http://127.0.0.1:5000&quot;, &quot;your_api_key&quot;, &quot;Meta Strategy&quot;);</span></span></code></pre></div><hr><p><strong>Notes</strong></p><ul><li>Replace placeholder values like <code>&quot;your_api_key&quot;</code> and <code>&quot;http://127.0.0.1:5000&quot;</code> with the actual key and URL for your setup.</li><li><code>symbolParam</code> is the Tradeboard symbol, not the MetaTrader symbol. Equities carry no <code>-EQ</code> suffix, so use <code>SBIN</code>, not <code>SBIN-EQ</code>.</li><li>The transport is <code>wininet.dll</code>, so <strong>Allow DLL imports</strong> must be enabled for the EA. MQL5&#39;s <code>WebRequest()</code> allowlist is not involved.</li><li>Tradeboard rate limits order placement to 10 requests per second. Guard your EA against firing on every tick.</li><li>This library covers order management only. Market data, the order book, positions and holdings are reached by calling the Tradeboard REST API directly.</li></ul>`,54)])])}const m=e(r,[["render",o]]);export{u as __pageData,m as default};
